import type { NextConfig } from 'next';

/**
 * GitHub Pages is static hosting, so the app is exported as plain files.
 *
 * Two consequences worth knowing:
 *  - No image optimizer. Formats are negotiated by <picture> against AVIF
 *    files generated by scripts/make-avif.py (see src/ui/components/Art.tsx).
 *  - No server, so no Route Handlers. The MongoDB sync layer in
 *    BUILD_PROMPT.md section 9.2 cannot run here; play state stays local in
 *    IndexedDB until the app is hosted somewhere with a server.
 *
 * Neither limits the game itself: the model is on-device, so the whole thing
 * works offline anyway.
 */
const basePath = process.env.NEXT_PUBLIC_BASE_PATH ?? '';

const nextConfig: NextConfig = {
  output: 'export',
  basePath,
  reactStrictMode: true,
  trailingSlash: true,          // /create/ resolves to create/index.html on Pages
  images: { unoptimized: true },
  devIndicators: false,
};

export default nextConfig;
